css:
[data-bz-section="cta-band"] .bz-block { padding-block: 0; }
[data-bz-section="cta-band"] .bz-block p { color: rgba(255,255,255,.82); max-width: 56ch; margin: 0 auto; }
[data-bz-section="cta-band"] .bz-btns { justify-content: center; margin-bottom: 0; }
[data-bz-section="cta-band"] .bz-btn { background: #fff; color: var(--ink); border-color: #fff; }
[data-bz-section="cta-band"] .bz-btn + .bz-btn { background: transparent; color: #fff; border-color: rgba(255,255,255,.6); }
